def 分鱼干(份数):
    if 份数 <= 0:
        raise ValueError("份数得是正数喵")
    return 份数 * {b}

for 一份 in [{a}, 0]:
    try:
        print("分到", 分鱼干(一份))
    except Exception as e:
        print("纸条上的名字：", type(e).__name__)
